const input=$json.body??$json;
const text=v=>v===null||v===undefined?'':String(v).trim();
const bool=v=>typeof v==='boolean'?v:['true','1','yes','on'].includes(text(v).toLowerCase());

const action=text(input.action||'list').toLowerCase();
const clinic_name=text(input.clinic_name);
const doctor_id=Number(input.doctor_id??0);
const doctor_name=text(input.doctor_name);
const schedule_id=Number(input.schedule_id??0);
const weekday=Number(input.weekday??0);
const start_time=text(input.start_time);
const end_time=text(input.end_time);
const valid_from=text(input.valid_from);
const valid_to=text(input.valid_to);
const actor_name=text(input.actor_name);
const source_channel=text(input.source_channel||'api').toLowerCase();
const confirm_action=bool(input.confirm_action);

const actions=['create','update','activate','deactivate','get','list'];
const errors=[];

if(!actions.includes(action))errors.push({field:'action',message:'اقدام معتبر نیست.'});
if(!clinic_name)errors.push({field:'clinic_name',message:'نام کلینیک الزامی است.'});
if(!Number.isInteger(doctor_id)||doctor_id<0)errors.push({field:'doctor_id',message:'شناسه پزشک معتبر نیست.'});
if(doctor_id<1&&!doctor_name)errors.push({field:'doctor_reference',message:'شناسه یا نام پزشک الزامی است.'});
if(!Number.isInteger(schedule_id)||schedule_id<0)errors.push({field:'schedule_id',message:'شناسه برنامه معتبر نیست.'});
if(['update','activate','deactivate','get'].includes(action)&&schedule_id<1){
 errors.push({field:'schedule_id',message:'برای این اقدام شناسه برنامه الزامی است.'});
}
if(['create','update'].includes(action)){
 if(!Number.isInteger(weekday)||weekday<1||weekday>7)errors.push({field:'weekday',message:'روز هفته باید بین 1 و 7 باشد.'});
 if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(start_time))errors.push({field:'start_time',message:'ساعت شروع معتبر نیست.'});
 if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(end_time))errors.push({field:'end_time',message:'ساعت پایان معتبر نیست.'});
 if(start_time&&end_time&&end_time<=start_time)errors.push({field:'time_range',message:'ساعت پایان باید بعد از ساعت شروع باشد.'});
}
if(valid_from&&!/^\d{4}-\d{2}-\d{2}$/.test(valid_from))errors.push({field:'valid_from',message:'تاریخ شروع باید YYYY-MM-DD باشد.'});
if(valid_to&&!/^\d{4}-\d{2}-\d{2}$/.test(valid_to))errors.push({field:'valid_to',message:'تاریخ پایان باید YYYY-MM-DD باشد.'});
if(valid_from&&valid_to&&valid_to<valid_from)errors.push({field:'validity_range',message:'تاریخ پایان اعتبار باید بعد از شروع باشد.'});
if(!['api','manual','import','system'].includes(source_channel))errors.push({field:'source_channel',message:'کانال منبع معتبر نیست.'});
if(!['get','list'].includes(action)&&!actor_name)errors.push({field:'actor_name',message:'نام انجام‌دهنده الزامی است.'});
if(!['get','list'].includes(action)&&confirm_action!==true)errors.push({field:'confirm_action',message:'اقدام باید تأیید شود.'});

return [{json:{
 action,clinic_name,doctor_id,doctor_name,schedule_id,weekday,start_time,end_time,
 valid_from,valid_to,actor_name,source_channel,confirm_action,
 validation_status:errors.length?'invalid':'valid',errors
}}];
